    std::uint64_t *aOUSaltD = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltD;
    std::uint64_t *aOUSaltE = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltE;
