            aOrbiterG = ((aWandererK + RotL64(aScatter, 11U)) + RotL64(aCarry, 27U)) + 0x02F4FAB08AB38DDEULL;
            aOrbiterK = (aWandererJ + RotL64(aCross, 3U)) + 0xA4A57F6CC435FB9CULL;
            aOrbiterA = ((aWandererF + RotL64(aPrevious, 27U)) + 0x2DE235220CE871A1ULL) + aOASaltE[(((511U - aIndex) + 324U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aIngress, 53U)) + RotL64(aCarry, 39U)) + 0xD0ECFDD05F4051CEULL;
            aOrbiterH = (aWandererD + RotL64(aScatter, 60U)) + 0x131F969EB116BA1FULL;
            aOrbiterE = ((aWandererE + RotL64(aIngress, 37U)) + 0x450889A629997B33ULL) + aOASaltF[((aIndex + 457U)) & S_SALT1];
