            aCross ^= (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 14601U)) & S_BLOCK1], 6U) ^ RotL64(pCrossLaneD[((aIndex + 13672U)) & S_BLOCK1], 53U));
            aCross = TwistMix64::DiffuseA((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 29U) ^ RotL64(aCross, 41U)) + (RotL64(aCarry, 5U) ^ RotL64(aPrevious, 56U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterJ = (aWandererD + RotL64(aIngress, 19U)) + 0xE40B8114B41C61B6ULL;
            aOrbiterD = ((aWandererH + RotL64(aCross, 5U)) + 0x66E842CEE59B88EAULL) + aOASaltA[(((511U - aIndex) + 209U)) & S_SALT1];
            aOrbiterF = (((aWandererC + RotL64(aScatter, 29U)) + RotL64(aCarry, 3U)) + 0xDBF713B63CD392C6ULL) + aOASaltD[(((511U - aIndex) + 428U)) & S_SALT1];
            aOrbiterE = ((aWandererE + RotL64(aPrevious, 37U)) + RotL64(aCarry, 37U)) + 0xE492349EFC119757ULL;
            aOrbiterB = (aWandererF + RotL64(aIngress, 51U)) + 0xA21F1DE4233F5390ULL;
            aOrbiterI = ((aWandererB + RotL64(aScatter, 12U)) + 0x10393B2F7E642C0CULL) + aOASaltE[((aIndex + 297U)) & S_SALT1];
            aOrbiterA = (((aWandererK + RotL64(aCross, 43U)) + RotL64(aCarry, 19U)) + 0x139998468F5757E2ULL) + aOASaltG[(((511U - aIndex) + 377U)) & S_SALT1];
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x5C39F5C0E20741B6ULL) + aOUSaltF[(((511U - aIndex) + 413U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterJ) ^ 0x0B4BCB8FE84F288DULL) ^ aOUSaltC[((aIndex + 59U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x8F70FDA26F73FB87ULL), 39U);
