            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0xA3C2CFCFD6A10F98ULL) + aOUSaltH[((aIndex + 209U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x2767D1577DC97A20ULL;
