            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xFBB58C4554A7E181ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterG) ^ 0x4B8AF40693C35F9BULL) ^ aOUSaltH[((aIndex + 193U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xAF6EDD2CEB61B651ULL), 13U);
